using System;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using MeshFrame.Core;
using MeshFrame.UI;
class Regression {
 static int pass,fail;
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}
 static void Test(string name,Action f){try{f();pass++;Console.WriteLine("PASS "+name);}catch(Exception e){fail++;Console.WriteLine("FAIL "+name+": "+e.GetBaseException().Message);}}
 static V3[] Rect(double l=5000,double h=800){return new[]{new V3(0,0,0),new V3(l,0,0),new V3(l,h,0),new V3(0,h,0)};}
 static MeshFramePlan Plan(MeshFrameSettings s,V3[] p){Frame f;V2[] poly;string e;Check(MeshFrameBuilder.TryFrame(p,s.AnchorPoint-1,out f,out poly,out e),e);return MeshFramePlanner.Plan(s,poly);}
 [STAThread] static int Main(){Application.EnableVisualStyles();
  Test("5000x1800 with 2500 cells has no fixed standard warnings",()=>{var s=new MeshFrameSettings{StiffMax=2500};var p=Plan(s,Rect(5000,1800));Check(p.Errors.Count==0,string.Join(";",p.Errors));Check(!p.Warnings.Any(x=>x.Contains("chuẩn")||x.Contains("tối đa 4000")||x.Contains("tối đa 1200")),string.Join(";",p.Warnings));});
  foreach(bool trap in new[]{false,true}) foreach(int anchor in new[]{1,2,3,4}) foreach(int cell in new[]{0,1,4}){
   bool t=trap;int a=anchor,c=cell;Test("cell edit "+c+" anchor "+a+" trapezoid="+t,()=>{var pts=Rect();if(t)pts[3]=new V3(-50,800,0);var s=new MeshFrameSettings{AnchorPoint=a,StiffBaseEdge=1,StiffMode=StiffMode.Custom,StiffCells=t?"1000 1000 1000 1000 1050":"1000 1000 1000 1000 1000"};var p=Plan(s,pts);Frame f;V2[] poly;string e;MeshFrameBuilder.TryFrame(pts,a-1,out f,out poly,out e);var r=DimEdit.Apply(p,f,s,pts,DimKind.Cell,c,1500);Check(r.Ok,r.Error);Check((r.Points[a-1]-pts[a-1]).Length<1e-6,"anchor moved");var after=Plan(r.Settings,r.Points);Check(after.Cells.Count==p.Cells.Count,"cell count changed");int balance=(a==1||a==4)?p.Cells.Count-1:0;if(balance==c)balance=balance==0?p.Cells.Count-1:0;for(int k=0;k<p.Cells.Count;k++)Check(Math.Abs(after.Cells[k]-(k==c?1500:k==balance?p.Cells[k]-(1500-p.Cells[c]):p.Cells[k]))<.01,"unexpected cell "+k);for(int k=0;k<pts.Length;k++)Check((pts[k]-r.Points[k]).Length<1e-8,"main frame resized");});}
  foreach(StripPosKind pos in Enum.GetValues(typeof(StripPosKind))) Test("perimeter strips at V edge "+pos,()=>{var s=new MeshFrameSettings{VLegA=50,VLegB=50,StripWidth=30,StripPos=pos};var p=Plan(s,Rect());var st=p.Strips.First(x=>!x.OnStiffener);Check(Math.Abs(st.Start.Y-15)<1e-6,"perimeter strip moved");Check(p.Strips.Any(x=>x.OnStiffener),"missing stiff strips");});
  Test("coordinate edit can switch grid cell without reentrant exception",()=>{using(var d=new MeshFrameDialog()){d.Points=Rect();d.Show();Application.DoEvents();var grid=(DataGridView)typeof(MeshFrameDialog).GetField("_grid",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);grid.CurrentCell=grid.Rows[0].Cells[1];grid.BeginEdit(true);((TextBox)grid.EditingControl).Text="-50";grid.CurrentCell=grid.Rows[1].Cells[2];Application.DoEvents();Check(Math.Abs(d.Points[0].X+50)<1e-6,"coordinate edit not applied");d.Close();}});
  Test("empty editor does not invoke PickHandler",()=>{using(var d=new MeshFrameDialog()){int picks=0;d.PickHandler=()=>{picks++;return Rect();};d.Show();Application.DoEvents();Check(picks==0,"picked on startup");Check(d.Points.Length==0,"startup has points");var b=(Button)typeof(MeshFrameDialog).GetField("_btnRepick",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);b.PerformClick();Application.DoEvents();Check(picks==1&&d.Points.Length==4,"button did not pick");d.Close();}});
  Test("create result remains visible after successful button click",()=>{using(var d=new MeshFrameDialog()){d.CreateHandler=(s,p)=>new CreateOutcome{Success=true,Message="VISIBLE_CREATE_RESULT"};d.Points=Rect();d.Show();Application.DoEvents();var b=(Button)typeof(MeshFrameDialog).GetField("_btnCreate",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);b.PerformClick();var status=(RichTextBox)typeof(MeshFrameDialog).GetField("_status",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);Check(status.Text.Contains("VISIBLE_CREATE_RESULT"),"result erased after create");d.Close();}});
  foreach(bool skew in new[]{false,true}) {bool shape=skew;Test("miter strip outer corners match frame "+shape,()=>{var s=new MeshFrameSettings{VLegA=50,VLegB=50,StripWidth=30,StripThk=3};var pts=Rect(3465,505);if(shape)pts[3]=new V3(-53.04,505,0);var p=Plan(s,pts);var v=Model3D.Build(p);double area=0;for(int i=0;i<4;i++){var pr=v.Prisms.First(x=>x.Kind==PartKind.Strip&&x.Index==i);area+=Math.Abs(Geo.Area(pr.Poly));Check(pr.Poly.Any(q=>(q-p.Polygon[i]).Length<1e-6),"missing outer miter tip at start "+i);Check(pr.Poly.Any(q=>(q-p.Polygon[(i+1)%4]).Length<1e-6),"missing outer miter tip at end "+i);}double ring=Math.Abs(Geo.Area(p.Polygon))-Math.Abs(Geo.Area(Geo.Offset(p.Polygon,30)));Check(Math.Abs(area-ring)<.01,"miter gaps/overlaps in ring");});}
  Test("P3 anchor persists when points are loaded",()=>{using(var d=new MeshFrameDialog()){d.Settings=new MeshFrameSettings{AnchorPoint=3};d.Points=Rect();Check(d.Settings.AnchorPoint==3,"anchor reset to P1");d.Points=Rect(6000);Check(d.Settings.AnchorPoint==3,"anchor reset on replacing points");}});
  Test("origin selector changes anchor and follows point click",()=>{using(var d=new MeshFrameDialog()){d.Points=Rect();d.Show();Application.DoEvents();var controls=(System.Collections.Generic.Dictionary<string,Control>)typeof(MeshFrameDialog).GetField("_ctl",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);var combo=(ComboBox)controls["AnchorPoint"];Check(combo.Items.Count==4,"missing anchor choices");combo.SelectedIndex=2;Check(d.Settings.AnchorPoint==3,"P3 selector did not update settings");typeof(MeshFrameDialog).GetMethod("OnAnchorPicked",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(d,new object[]{3});Check(combo.SelectedIndex==3&&d.Settings.AnchorPoint==4,"point click not synchronized");d.Close();}});
  Test("loading existing frame preserves its chosen origin",()=>{using(var d=new MeshFrameDialog()){d.EditHandler=()=>new LoadedFrame{Id="fixture",Points=Rect(),Settings=new MeshFrameSettings{AnchorPoint=4}};d.Show();Application.DoEvents();((Button)typeof(MeshFrameDialog).GetField("_btnEdit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d)).PerformClick();Check(d.Settings.AnchorPoint==4,"existing origin changed");d.Close();}});
  Test("frame record stores pose and native endpoints",()=>{var r=new FrameRecord{Id="pose",Corners=Rect(),NativeReference=new[]{new V3(1,2,3),new V3(2,2,3),new V3(1,3,3)}};r.Settings.AnchorPoint=3;r.NativeBars["B0"]=new[]{new V3(1,2,3),new V3(10,2,3)};string path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"meshframe-pose-test.mfr");r.Save(path);var n=FrameRecord.Load(path);Check(n!=null&&n.NativeReference.Length==3&&n.NativeBars.Count==1&&n.Settings.AnchorPoint==3,"pose data not persisted");System.IO.File.Delete(path);});
  Test("changing origin selection does not move geometry",()=>{using(var d=new MeshFrameDialog()){d.Points=Rect();var before=(V3[])d.Points.Clone();var controls=(System.Collections.Generic.Dictionary<string,Control>)typeof(MeshFrameDialog).GetField("_ctl",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);((ComboBox)controls["AnchorPoint"]).SelectedIndex=3;Check(d.Settings.AnchorPoint==4,"P4 not chosen");for(int i=0;i<4;i++)Check((before[i]-d.Points[i]).Length<1e-8,"origin selector moved a point");}});
  Test("chosen origin XYZ remains editable in coordinates table",()=>{using(var d=new MeshFrameDialog()){d.Settings=new MeshFrameSettings{AnchorPoint=3};d.Points=Rect();d.Show();Application.DoEvents();var grid=(DataGridView)typeof(MeshFrameDialog).GetField("_grid",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d);grid.CurrentCell=grid.Rows[2].Cells[1];grid.BeginEdit(true);((TextBox)grid.EditingControl).Text="5100";grid.CurrentCell=grid.Rows[2].Cells[2];Application.DoEvents();Check(d.Settings.AnchorPoint==3&&Math.Abs(d.Points[2].X-5100)<1e-6,"origin coordinates locked or origin reset");d.Close();}});
  Test("3640 screenshot example preserves all frame corners",()=>{var pts=Rect(3640,500);var s=new MeshFrameSettings{StiffMode=StiffMode.Custom,StiffCells="1000 1000 1000 640",StiffBaseEdge=1};Frame f;V2[] poly;string e;MeshFrameBuilder.TryFrame(pts,0,out f,out poly,out e);var r=DimEdit.Apply(Plan(s,pts),f,s,pts,DimKind.Cell,1,1500);Check(r.Ok,r.Error);var after=Plan(r.Settings,r.Points);Check(after.Cells.SequenceEqual(new[]{1000.0,1500.0,1000.0,140.0}),"wrong remainder");Check(Math.Abs((r.Points[1]-r.Points[0]).Length-3640)<1e-8,"3640 changed");});
  Test("1000 terminal reduces to 500 when middle increases by 500",()=>{var pts=Rect(4000);var s=new MeshFrameSettings{StiffMode=StiffMode.Custom,StiffCells="1000 1000 1000 1000",StiffBaseEdge=1};Frame f;V2[] poly;string e;MeshFrameBuilder.TryFrame(pts,0,out f,out poly,out e);var r=DimEdit.Apply(Plan(s,pts),f,s,pts,DimKind.Cell,1,1500);Check(r.Ok,r.Error);Check(Plan(r.Settings,r.Points).Cells.Last()==500,"end cell not 500");});
  Test("not enough residual rejects edit without changing frame or settings",()=>{var pts=Rect(3640);var s=new MeshFrameSettings{StiffMode=StiffMode.Custom,StiffCells="1000 1000 1000 640",StiffBaseEdge=1};Frame f;V2[] poly;string e;MeshFrameBuilder.TryFrame(pts,0,out f,out poly,out e);var r=DimEdit.Apply(Plan(s,pts),f,s,pts,DimKind.Cell,1,2000);Check(!r.Ok&&r.Error.Contains("Không đủ chỗ"),"did not reject negative remainder");Check(s.StiffCells=="1000 1000 1000 640"&&pts[1].X==3640,"input mutated on rejection");});
  Test("editing a terminal compensates the opposite terminal",()=>{var pts=Rect(3640);var s=new MeshFrameSettings{StiffMode=StiffMode.Custom,StiffCells="1000 1000 1000 640",StiffBaseEdge=1};Frame f;V2[] poly;string e;MeshFrameBuilder.TryFrame(pts,0,out f,out poly,out e);var r=DimEdit.Apply(Plan(s,pts),f,s,pts,DimKind.Cell,3,500);Check(r.Ok,r.Error);var cells=Plan(r.Settings,r.Points).Cells;Check(cells.First()==1140&&cells.Last()==500,"opposite terminal not compensated");});
  Test("explicit frame edge dimension can still resize",()=>{var pts=Rect(3640);var s=new MeshFrameSettings();Frame f;V2[] poly;string e;MeshFrameBuilder.TryFrame(pts,0,out f,out poly,out e);var r=DimEdit.Apply(Plan(s,pts),f,s,pts,DimKind.Edge,0,5000);Check(r.Ok&&Math.Abs((r.Points[1]-r.Points[0]).Length-5000)<1e-6,"frame length incorrectly locked for edge edit");});
  Console.WriteLine("RESULT "+pass+" passed "+fail+" failed");return fail==0?0:1;
 }
}
